export function assert(e){if(!e)throw new Error("Assertion failed!")}export const haultImmediateEvent=e=>{e.preventDefault(),e.stopImmediatePropagation()};export const getMouseEventOffsets=(e,t)=>{const o=t.getBoundingClientRect();return{offsetX:e.clientX-o.x,offsetY:e.clientY-o.y}};export const getClickableTargetFromEvent=e=>{for(const t of e.composedPath()){if(!(t instanceof Element))continue;const e=t.getBoundingClientRect();if(0!==e.width&&0!==e.height)return t}throw new Error(`No target is found in event of type ${e.type}`)};export const createClickAttributes=(e,t)=>{let o;if(e instanceof PointerEvent)switch(e.pointerType){case"mouse":break;case"pen":case"touch":o=e.pointerType;break;default:return}const{offsetX:n,offsetY:r}=getMouseEventOffsets(e,t);if(!(n<0||r<0))return{button:["auxiliary","secondary","back","forward"][e.button-1],deviceType:o,offsetX:n,offsetY:r}};